"""csvquery: a from-scratch, stdlib-only CSV query engine.

Supported SQL subset:

    SELECT <alias.col> [, <alias.col> ...]
    FROM <table> [<alias>]
    [INNER] JOIN <table> [<alias>] ON <alias.col> = <alias.col>
    [WHERE <qualified col | literal> <op> <qualified col | literal>]
    [ORDER BY <alias.col> [ASC | DESC]]

The JOIN is executed as a classic hash join:
  * the build side is the input with the FEWER rows (by row count),
  * the other side is probed,
  * no nested loops anywhere.

An introspection hook is provided (see QueryEngine.add_hook and
QueryEngine.last_build_side) so callers can observe plan decisions.
"""

from __future__ import annotations

import csv
import operator
import re
from pathlib import Path


class QueryError(Exception):
    """Raised for any parse or execution problem."""


# --------------------------------------------------------------------------
# Tokenizer
# --------------------------------------------------------------------------

_TOKEN_RE = re.compile(
    r"""
      (?P<ws>\s+)
    | (?P<number>-?\d+(?:\.\d+)?)
    | (?P<string>'(?:[^']|'')*')
    | (?P<ident>[A-Za-z_][A-Za-z0-9_]*)
    | (?P<op><=|>=|!=|<>|=|<|>)
    | (?P<punct>[.,;()])
    """,
    re.VERBOSE,
)

KEYWORDS = {
    "SELECT", "FROM", "JOIN", "INNER", "ON", "WHERE",
    "ORDER", "BY", "ASC", "DESC", "GROUP", "LEFT", "RIGHT", "OUTER",
}


def tokenize(sql: str):
    tokens = []
    pos = 0
    while pos < len(sql):
        m = _TOKEN_RE.match(sql, pos)
        if not m:
            raise QueryError(f"unexpected character {sql[pos]!r} at position {pos}")
        pos = m.end()
        kind = m.lastgroup
        if kind == "ws":
            continue
        tokens.append((kind, m.group()))
    return tokens


# --------------------------------------------------------------------------
# Value coercion: CSV cells are strings; make numbers numeric so that
# comparisons, joins and ORDER BY behave like a typed database.
# --------------------------------------------------------------------------

_INT_RE = re.compile(r"^[+-]?\d+$")
_FLOAT_RE = re.compile(r"^[+-]?(\d+\.\d*|\.\d+)$")


def coerce(cell: str):
    if _INT_RE.match(cell):
        return int(cell)
    if _FLOAT_RE.match(cell):
        return float(cell)
    return cell


# --------------------------------------------------------------------------
# Parser -> AST dict
# --------------------------------------------------------------------------

class _Parser:
    def __init__(self, sql: str):
        self.sql = sql
        self.toks = tokenize(sql)
        self.i = 0

    # -- token helpers ------------------------------------------------------
    def peek(self):
        return self.toks[self.i] if self.i < len(self.toks) else None

    def next(self):
        tok = self.peek()
        if tok is None:
            raise QueryError(f"unexpected end of query: {self.sql!r}")
        self.i += 1
        return tok

    def at_keyword(self, *kws):
        tok = self.peek()
        return (
            tok is not None
            and tok[0] == "ident"
            and tok[1].upper() in kws
        )

    def expect_keyword(self, kw):
        kind, text = self.next()
        if kind != "ident" or text.upper() != kw:
            raise QueryError(f"expected {kw}, got {text!r}")

    def accept_keyword(self, kw):
        if self.at_keyword(kw):
            self.next()
            return True
        return False

    def expect_punct(self, ch):
        kind, text = self.next()
        if kind != "punct" or text != ch:
            raise QueryError(f"expected {ch!r}, got {text!r}")

    def expect_ident(self):
        kind, text = self.next()
        if kind != "ident":
            raise QueryError(f"expected identifier, got {text!r}")
        return text

    # -- grammar ------------------------------------------------------------
    def qualified_column(self):
        alias = self.expect_ident()
        self.expect_punct(".")
        col = self.expect_ident()
        return (alias, col)

    def operand(self):
        """A qualified column or a literal (number / 'string')."""
        tok = self.peek()
        if tok is None:
            raise QueryError("unexpected end of query inside expression")
        kind, text = tok
        if kind == "number":
            self.next()
            return ("lit", coerce(text))
        if kind == "string":
            self.next()
            return ("lit", text[1:-1].replace("''", "'"))
        if kind == "ident" and text.upper() not in KEYWORDS:
            return ("col", self.qualified_column())
        raise QueryError(f"expected column or literal, got {text!r}")

    def table_ref(self):
        name = self.expect_ident()
        nxt = self.peek()
        if nxt is not None and nxt[0] == "ident" and nxt[1].upper() not in KEYWORDS:
            alias = self.next()[1]
        else:
            alias = name
        return name, alias

    def parse(self):
        ast = {}

        self.expect_keyword("SELECT")
        select_items = [self.qualified_column()]
        while self.peek() and self.peek()[:2] == ("punct", ","):
            self.next()
            select_items.append(self.qualified_column())
        ast["select"] = select_items

        self.expect_keyword("FROM")
        ast["from"], from_alias = (*self.table_ref(),)[0], None
        name, alias = None, None
        self.i -= 1  # reparse via table_ref below
        name, alias = self.table_ref()
        ast["from"], ast["from_alias"] = name, alias

        if self.at_keyword("INNER"):
            self.next()
        self.expect_keyword("JOIN")
        jname, jalias = self.table_ref()
        ast["join"], ast["join_alias"] = jname, jalias

        self.expect_keyword("ON")
        left = self.qualified_column()
        kind, op = self.next()
        if kind != "op" or op != "=":
            raise QueryError("only equality (=) is supported in ON")
        right = self.qualified_column()
        ast["on"] = (left, right)

        if self.accept_keyword("WHERE"):
            wleft = self.operand()
            kind, op = self.next()
            if kind != "op":
                raise QueryError(f"expected comparison operator, got {op!r}")
            if op == "<>":
                op = "!="
            wright = self.operand()
            ast["where"] = (wleft, op, wright)

        if self.accept_keyword("ORDER"):
            self.expect_keyword("BY")
            col = self.qualified_column()
            descending = False
            if self.accept_keyword("DESC"):
                descending = True
            else:
                self.accept_keyword("ASC")
            ast["order_by"] = col
            ast["desc"] = descending

        tail = self.peek()
        if tail is not None:
            if tail[0] == "punct" and tail[1] == ";" and self.i == len(self.toks) - 1:
                self.next()
            else:
                raise QueryError(f"unexpected trailing token {tail[1]!r}")
        if self.i != len(self.toks):
            raise QueryError("unexpected trailing tokens after semicolon")

        return ast


# --------------------------------------------------------------------------
# Execution engine
# --------------------------------------------------------------------------

_CMP_OPS = {
    "=": operator.eq,
    "!=": operator.ne,
    "<": operator.lt,
    "<=": operator.le,
    ">": operator.gt,
    ">=": operator.ge,
}


class QueryEngine:
    """Loads CSV tables lazily and executes the supported SQL subset."""

    def __init__(self, data_dir="."):
        self.data_dir = Path(data_dir)
        self._tables = {}          # name -> list[dict[col -> value]]
        self.hooks = []            # callables(event: dict)
        self.last_build_side = None  # (alias, table_name, row_count)

    # -- introspection -------------------------------------------------------
    def add_hook(self, fn):
        """Register fn(event: dict). Events include:
            {"event": "build_side", "alias": ..., "table": ..., "rows": N}
            {"event": "probe_side", "alias": ..., "table": ..., "rows": N}
        """
        self.hooks.append(fn)

    def _emit(self, event):
        for fn in self.hooks:
            fn(event)

    # -- storage --------------------------------------------------------------
    def _load(self, table):
        if table not in self._tables:
            path = self.data_dir / f"{table}.csv"
            if not path.exists():
                raise QueryError(f"unknown table {table!r} ({path} not found)")
            with open(path, newline="", encoding="utf-8") as fh:
                rows = [
                    {col: coerce(val) for col, val in rec.items()}
                    for rec in csv.DictReader(fh)
                ]
            self._tables[table] = rows
        return self._tables[table]

    # -- hash join -------------------------------------------------------------
    def _hash_join(self, ast):
        left_rows = self._load(ast["from"])
        right_rows = self._load(ast["join"])
        lalias, ralias = ast["from_alias"], ast["join_alias"]

        # Build side = smaller file by row count (ties -> left side).
        if len(right_rows) <= len(left_rows):
            build_alias, build_rows = ralias, right_rows
            probe_alias, probe_rows = lalias, left_rows
        else:
            build_alias, build_rows = lalias, left_rows
            probe_alias, probe_rows = ralias, right_rows

        (on_l_alias, on_l_col), (on_r_alias, on_r_col) = ast["on"]
        aliases = {on_l_alias, on_r_alias}
        if aliases != {lalias, ralias}:
            raise QueryError(
                f"ON clause must reference the two joined tables {lalias!r} and {ralias!r}"
            )
        if on_l_alias == on_r_alias:
            raise QueryError("ON clause must reference both sides of the join")

        build_key = (on_l_col, on_r_col)
        build_key = on_l_col if on_l_alias == build_alias else on_r_col
        probe_key = on_r_col if on_l_alias == build_alias else on_l_col

        self.last_build_side = (build_alias, ast["join" if build_alias == ralias else "from"],
                                len(build_rows))
        self._emit({"event": "build_side", "alias": build_alias,
                    "table": self.last_build_side[1], "rows": len(build_rows)})
        self._emit({"event": "probe_side", "alias": probe_alias,
                    "table": self.last_build_side[1 + (build_alias == probe_alias)],
                    "rows": len(probe_rows)})
        # fix probe table name cleanly (the line above is intentionally simple;
        # compute explicitly to avoid confusion)
        probe_table = ast["from"] if probe_alias == ast["from_alias"] else ast["join"]
        self.last_probe_side = (probe_alias, probe_table, len(probe_rows))

        # Build phase: single pass over the smaller input.
        index = {}
        for row in build_rows:
            index.setdefault(row[build_key], []).append(row)

        # Probe phase: single pass over the larger input.
        joined = []
        for probe_row in probe_rows:
            key = probe_row[probe_key]
            matches = index.get(key)
            if not matches:
                continue  # INNER JOIN: no match -> row vanishes
            for build_row in matches:
                combined = {}
                for col, val in build_row.items():
                    combined[(build_alias, col)] = val
                for col, val in probe_row.items():
                    combined[(probe_alias, col)] = val
                joined.append(combined)
        return joined

    # -- WHERE / ORDER BY / projection ------------------------------------------
    @staticmethod
    def _resolve(operand, row):
        kind, payload = operand
        if kind == "lit":
            return payload
        return row[payload]

    def execute(self, sql: str):
        ast = _Parser(sql).parse()

        rows = self._hash_join(ast)

        if "where" in ast:
            wleft, op, wright = ast["where"]
            cmp_fn = _CMP_OPS[op]
            rows = [
                r for r in rows
                if cmp_fn(self._resolve(wleft, r), self._resolve(wright, r))
            ]

        if "order_by" in ast:
            order_col = ast["order_by"]
            try:
                rows.sort(key=lambda r: r[order_col], reverse=ast["desc"])
            except TypeError as exc:
                raise QueryError(f"cannot ORDER BY {order_col}: {exc}") from exc

        return [tuple(r[col] for col in ast["select"]) for r in rows]

